import { describe, expect, it } from "vitest";
import { normalizeTrace } from "../normalize";
import { aiSdkDevtoolsAdapter } from "./ai-sdk-devtools";

interface StepOverrides {
  run_id?: string;
  step_number?: number;
  model_id?: string;
  duration_ms?: number | null;
  input?: unknown;
  output?: unknown;
  usage?: unknown;
  error?: string | null;
}

const SYSTEM = { role: "system", content: "You are a weather bot." };
const USER = { role: "user", content: [{ type: "text", text: "Weather in SF?" }] };
const ASSISTANT_CALL = {
  role: "assistant",
  content: [
    { type: "reasoning", text: "Need the tool." },
    { type: "tool-call", toolCallId: "call_1", toolName: "getWeather", input: { city: "SF" } },
  ],
};
const TOOL_RESULT = {
  role: "tool",
  content: [
    {
      type: "tool-result",
      toolCallId: "call_1",
      toolName: "getWeather",
      output: { type: "json", value: { tempC: 18 } },
    },
  ],
};
const ASSISTANT_ANSWER = {
  role: "assistant",
  content: [{ type: "text", text: "18C and sunny." }],
};

const USAGE = {
  inputTokens: 100,
  inputTokenDetails: { noCacheTokens: 100, cacheReadTokens: 0, cacheWriteTokens: 0 },
  outputTokens: 20,
  outputTokenDetails: { textTokens: 15, reasoningTokens: 5 },
  totalTokens: 120,
};

function step(overrides: StepOverrides = {}) {
  const { input, output, usage, ...rest } = overrides;
  return {
    id: `step-${rest.run_id ?? "r1"}-${rest.step_number ?? 1}`,
    run_id: "r1",
    step_number: 1,
    type: "generate",
    model_id: "test-model",
    provider: "test",
    started_at: "2026-08-25T10:00:00.000Z",
    duration_ms: 150,
    input: JSON.stringify(input ?? { prompt: [SYSTEM, USER] }),
    output: output === null ? null : JSON.stringify(output ?? { response: { messages: [] } }),
    usage: usage === null ? null : JSON.stringify(usage ?? USAGE),
    error: null,
    ...rest,
  };
}

function run(id: string, extra: Record<string, unknown> = {}) {
  return {
    id,
    started_at: "2026-08-25T10:00:00.000Z",
    parent_run_id: null,
    parent_step_id: null,
    function_id: null,
    ...extra,
  };
}

/** A two-step tool-using run: the shape the telemetry integration writes. */
function twoStepDb() {
  return {
    runs: [run("r1")],
    steps: [
      step({
        step_number: 1,
        input: { prompt: [SYSTEM, USER], tools: [{ name: "getWeather", description: "d" }] },
        output: { response: { messages: [ASSISTANT_CALL, TOOL_RESULT] } },
      }),
      step({
        step_number: 2,
        input: { prompt: [SYSTEM, USER, ASSISTANT_CALL, TOOL_RESULT] },
        output: { response: { messages: [ASSISTANT_ANSWER] } },
        usage: { ...USAGE, inputTokens: 130, inputTokenDetails: { cacheReadTokens: 100 } },
      }),
    ],
  };
}

describe("detect", () => {
  it("accepts a devtools database", () => {
    expect(aiSdkDevtoolsAdapter.detect(twoStepDb())).toBe(true);
    expect(aiSdkDevtoolsAdapter.detect({ runs: [], steps: [] })).toBe(true);
  });

  it("rejects other trace shapes", () => {
    expect(aiSdkDevtoolsAdapter.detect({ events: [] })).toBe(false);
    expect(aiSdkDevtoolsAdapter.detect({ info: {}, messages: [] })).toBe(false);
    expect(aiSdkDevtoolsAdapter.detect({ runs: [{}], steps: [] })).toBe(false);
    expect(aiSdkDevtoolsAdapter.detect(null)).toBe(false);
  });
});

describe("adapt", () => {
  it("keeps a multi-step run in one segment with paired tool calls", () => {
    const trace = normalizeTrace(aiSdkDevtoolsAdapter.adapt(twoStepDb()));
    expect(trace.segmentCount).toBe(1);
    expect(trace.generations).toHaveLength(2);

    const [first, second] = trace.generations;
    expect(first!.carriedMessages).toBe(0);
    // the step's own response rides in its snapshot; next step carries it all
    expect(second!.carriedMessages).toBe(4);

    const call = first!.newMessages.find((m) => m.toolCalls)?.toolCalls?.[0];
    expect(call?.name).toBe("getWeather");
    expect(call?.result).toContain("tempC");
    // paired results fold under their call instead of rendering as messages
    expect(first!.foldedResults).toBe(1);
  });

  it("splits reasoning out of assistant text", () => {
    const trace = normalizeTrace(aiSdkDevtoolsAdapter.adapt(twoStepDb()));
    const assistant = trace.generations[0]!.newMessages.at(-1)!;
    expect(assistant.reasoning).toBe("Need the tool.");
    expect(assistant.text).not.toContain("Need the tool.");
  });

  it("maps usage: totals, cache reads, reasoning tokens", () => {
    const trace = normalizeTrace(aiSdkDevtoolsAdapter.adapt(twoStepDb()));
    const [first, second] = trace.generations;
    expect(first!.metrics.inputTokens).toBe(100);
    expect(first!.metrics.reasoningTokens).toBe(5);
    expect(second!.metrics.inputTokens).toBe(130);
    expect(second!.breakdown.cacheableTokens).toBe(100);
  });

  it("handles legacy and provider-level usage shapes", () => {
    const legacy = normalizeTrace(
      aiSdkDevtoolsAdapter.adapt({
        runs: [run("r1")],
        steps: [step({ usage: { inputTokens: 50, outputTokens: 5, cachedInputTokens: 30 } })],
      }),
    );
    expect(legacy.generations[0]!.metrics.inputTokens).toBe(50);
    expect(legacy.generations[0]!.breakdown.cacheableTokens).toBe(30);

    const v4 = normalizeTrace(
      aiSdkDevtoolsAdapter.adapt({
        runs: [run("r1")],
        steps: [
          step({
            usage: {
              inputTokens: { total: 70, cacheRead: 40 },
              outputTokens: { total: 7, reasoning: 2 },
            },
          }),
        ],
      }),
    );
    expect(v4.generations[0]!.metrics.inputTokens).toBe(70);
    expect(v4.generations[0]!.metrics.reasoningTokens).toBe(2);
  });

  it("reconstructs middleware-shaped outputs (parts + stringified args)", () => {
    const trace = normalizeTrace(
      aiSdkDevtoolsAdapter.adapt({
        runs: [run("r1")],
        steps: [
          step({
            output: {
              textParts: [{ text: "partial" }],
              toolCalls: [
                { type: "tool-call", toolCallId: "c1", toolName: "grep", input: '{"q":"x"}' },
              ],
            },
          }),
        ],
      }),
    );
    const assistant = trace.generations[0]!.newMessages.at(-1)!;
    expect(assistant.text).toBe("partial");
    expect(assistant.toolCalls?.[0]?.args).toEqual({ q: "x" });
  });

  it("marks in-flight steps and errored steps", () => {
    const trace = normalizeTrace(
      aiSdkDevtoolsAdapter.adapt({
        runs: [run("r1")],
        steps: [
          step({ step_number: 1, duration_ms: null, output: null, usage: null }),
          step({ step_number: 2, error: "boom", output: null, usage: null }),
        ],
      }),
    );
    expect(trace.inProgress).toBe(true);
    expect(trace.generations[0]!.inProgress).toBe(true);
    expect(trace.generations[1]!.inProgress).toBeUndefined();
    expect(trace.generations[1]!.newMessages.at(-1)!.text).toContain("[error] boom");
  });
});

describe("split", () => {
  it("emits one part per run, children right after their parent", () => {
    const parts = aiSdkDevtoolsAdapter.split!({
      runs: [
        run("a"),
        run("b"),
        run("a-child", { parent_run_id: "a", parent_step_id: "step-a-1" }),
      ],
      steps: [step({ run_id: "a" }), step({ run_id: "b" }), step({ run_id: "a-child" })],
    });
    expect(parts.map((p) => p.runs[0]!.id)).toEqual(["a", "a-child", "b"]);
    for (const part of parts) {
      expect(part.steps.every((s) => s.run_id === part.runs[0]!.id)).toBe(true);
    }
  });

  it("treats a run with an unknown parent as a root", () => {
    const parts = aiSdkDevtoolsAdapter.split!({
      runs: [run("orphan", { parent_run_id: "gone" })],
      steps: [step({ run_id: "orphan" })],
    });
    expect(parts).toHaveLength(1);
  });

  it("records lineage on child parts", () => {
    const [child] = aiSdkDevtoolsAdapter.split!({
      runs: [run("child", { parent_run_id: "parent" })],
      steps: [step({ run_id: "child" })],
    }).map((part) => aiSdkDevtoolsAdapter.adapt(part));
    expect(child!.parent_trace_id).toBe("parent");
  });

  it("returns no parts for an empty database", () => {
    expect(aiSdkDevtoolsAdapter.split!({ runs: [], steps: [] })).toEqual([]);
  });
});

describe("trace naming", () => {
  it("labels a run by its last user message, collapsed and capped", () => {
    const raw = aiSdkDevtoolsAdapter.adapt({
      runs: [run("r1")],
      steps: [
        step({
          input: { prompt: [{ role: "user", content: `##  Title\n\n${"x".repeat(100)}` }] },
        }),
      ],
    });
    expect(raw.name.startsWith("## Title x")).toBe(true);
    expect(raw.name.length).toBeLessThanOrEqual(83);
  });

  it("prefers function_id and falls back for merged databases", () => {
    const named = aiSdkDevtoolsAdapter.adapt({
      runs: [run("r1", { function_id: "qa-agent" })],
      steps: [step({})],
    });
    expect(named.name).toBe("qa-agent");

    const merged = aiSdkDevtoolsAdapter.adapt({
      runs: [run("a"), run("b")],
      steps: [step({ run_id: "a" }), step({ run_id: "b" })],
    });
    expect(merged.name).toBe("AI SDK devtools session");
  });
});

import { spawn } from "node:child_process";

/** Opens a URL in the default browser, silently ignoring failures. */
export function openBrowser(url: string): void {
  const [command, args] =
    process.platform === "darwin"
      ? ["open", [url]]
      : process.platform === "win32"
        ? ["cmd", ["/c", "start", "", url]]
        : ["xdg-open", [url]];
  spawn(command, args, { stdio: "ignore", detached: true })
    .on("error", () => {})
    .unref();
}

/** Fetches a JSON api route, throwing the server's error message on failure. */
export async function fetchJson(url: string): Promise<unknown> {
  const res = await fetch(url);
  if (!res.ok) throw new Error((await res.json())?.error ?? `HTTP ${res.status}`);
  return res.json();
}

import { contentToText } from "../normalize";
import type { RawEvent, RawMessage, RawToolCall, RawToolDef, RawTrace } from "../types";
import type { TraceAdapter } from "./adapter";

/**
 * Adapter for AI SDK devtools databases ({runs[], steps[]}, written by
 * @ai-sdk/devtools to .devtools/generations.json). Each step's input.prompt
 * is already a cumulative snapshot of the conversation; appending the step's
 * own response messages yields the exact shape the pipeline speaks - the
 * next step's prompt repeats prompt + response verbatim, so segment
 * continuation and tool pairing work unchanged.
 *
 * A database holds many independent runs; split() turns every run - root or
 * nested child - into its own trace, children ordered right after their
 * parent. Children stay separate rather than bundled because the telemetry
 * integration can mis-attribute a concurrent sibling as a child (its
 * current-tool tracking is a process-wide singleton) - bundling would make
 * such a run invisible. adapt() on the whole database still yields one
 * merged trace for the text commands.
 */
export const aiSdkDevtoolsAdapter: TraceAdapter<DevtoolsDb> = {
  name: "ai-sdk-devtools",
  detect: isDevtoolsDb,
  adapt: adaptDevtoolsDb,
  split: splitDevtoolsDb,
};

interface DevtoolsDb {
  runs: DevtoolsRun[];
  steps: DevtoolsStep[];
}

interface DevtoolsRun {
  id: string;
  started_at?: string;
  parent_run_id?: string | null;
  function_id?: string | null;
}

interface DevtoolsStep {
  run_id: string;
  step_number: number;
  model_id?: string;
  provider?: string | null;
  started_at?: string;
  duration_ms?: number | null;
  input: string;
  output?: string | null;
  usage?: string | null;
  error?: string | null;
}

interface DevtoolsMessage {
  role: string;
  content: unknown;
}

interface DevtoolsPart {
  type?: string;
  text?: string;
  toolCallId?: string;
  toolName?: string;
  input?: unknown;
  output?: unknown;
}

interface DevtoolsInput {
  prompt?: DevtoolsMessage[];
  tools?: { name?: string; description?: string; parameters?: unknown }[];
}

interface DevtoolsOutput {
  content?: DevtoolsPart[];
  textParts?: { text?: string }[];
  reasoningParts?: { text?: string }[];
  toolCalls?: DevtoolsPart[];
  response?: { messages?: DevtoolsMessage[] };
}

interface DevtoolsUsage {
  inputTokens?: number | { total?: number; cacheRead?: number };
  outputTokens?: number | { total?: number; reasoning?: number };
  inputTokenDetails?: { cacheReadTokens?: number };
  outputTokenDetails?: { reasoningTokens?: number };
  cachedInputTokens?: number;
}

function isDevtoolsDb(raw: unknown): raw is DevtoolsDb {
  const t = raw as Partial<DevtoolsDb>;
  return (
    typeof t === "object" &&
    t !== null &&
    Array.isArray(t.runs) &&
    Array.isArray(t.steps) &&
    t.runs.every((r) => typeof r?.id === "string") &&
    t.steps.every((s) => typeof s?.run_id === "string" && typeof s?.input === "string")
  );
}

/** One part per run, depth-first so children list right after their parent. */
function splitDevtoolsDb(db: DevtoolsDb): DevtoolsDb[] {
  const known = new Set(db.runs.map((run) => run.id));
  // a run whose parent is not in the file cannot nest anywhere - treat as root
  const roots = db.runs.filter((run) => !run.parent_run_id || !known.has(run.parent_run_id));
  const children = new Map<string, DevtoolsRun[]>();
  for (const run of db.runs) {
    if (run.parent_run_id && known.has(run.parent_run_id)) {
      const siblings = children.get(run.parent_run_id) ?? [];
      siblings.push(run);
      children.set(run.parent_run_id, siblings);
    }
  }
  const ordered: DevtoolsRun[] = [];
  const visit = (run: DevtoolsRun) => {
    ordered.push(run);
    for (const child of children.get(run.id) ?? []) visit(child);
  };
  roots.forEach(visit);
  return ordered.map((run) => ({
    runs: [run],
    steps: db.steps.filter((step) => step.run_id === run.id),
  }));
}

function adaptDevtoolsDb(db: DevtoolsDb): RawTrace {
  const runs = new Map(db.runs.map((run) => [run.id, run]));
  // file order is append order (steps are written at step start), i.e.
  // chronological even when parent and child runs interleave
  const events = db.steps.map((step) => stepEvent(step, runs.get(step.run_id)));
  const started = [...runs.values()]
    .map((run) => run.started_at)
    .filter((t): t is string => typeof t === "string")
    .sort()[0];
  return {
    trace_id: db.runs[0]?.id ?? "ai-sdk-devtools",
    timestamp: started ?? db.steps[0]?.started_at ?? new Date(0).toISOString(),
    name: traceName(db),
    total_tokens: {
      input: events.reduce((acc, e) => acc + e.metrics.tokens.input, 0),
      output: events.reduce((acc, e) => acc + e.metrics.tokens.output, 0),
    },
    total_cost: 0,
    ...(events.some((e) => e.in_progress) ? { in_progress: true } : {}),
    ...(db.runs.length === 1 && db.runs[0]!.parent_run_id
      ? { parent_trace_id: db.runs[0]!.parent_run_id }
      : {}),
    events,
  };
}

/** A split part is one run - label it by its ask; a merged db keeps the generic name. */
function traceName(db: DevtoolsDb): string {
  const known = new Set(db.runs.map((run) => run.id));
  const roots = db.runs.filter((run) => !run.parent_run_id || !known.has(run.parent_run_id));
  const root = roots.length === 1 ? roots[0]! : undefined;
  if (!root) return "AI SDK devtools session";
  if (root.function_id) return root.function_id;
  const firstStep = db.steps.find((step) => step.run_id === root.id);
  const prompt = parseJson<DevtoolsInput>(firstStep?.input)?.prompt;
  const ask = prompt?.filter((message) => message.role === "user").at(-1);
  const text = ask ? contentToText(ask.content).replace(/\s+/g, " ").trim() : "";
  if (!text) return `run ${root.id.slice(-8)}`;
  return text.length > 80 ? `${text.slice(0, 80)}...` : text;
}

function stepEvent(step: DevtoolsStep, run: DevtoolsRun | undefined): RawEvent {
  const input = parseJson<DevtoolsInput>(step.input);
  const output = parseJson<DevtoolsOutput>(step.output);
  const response = responseMessages(output);
  const messages = [
    ...(input?.prompt ?? []).flatMap(convertMessage),
    ...response.flatMap(convertMessage),
    ...(step.error && response.length === 0
      ? [{ role: "assistant", content: `[error] ${step.error}` }]
      : []),
  ];
  return {
    type: "generation",
    name: run?.function_id ?? (run?.parent_run_id ? "nested run" : "ai-sdk"),
    model: step.model_id ?? "unknown",
    provider: step.provider ?? "unknown",
    ...(step.duration_ms == null && !step.error && !step.output ? { in_progress: true } : {}),
    metrics: {
      latency: (step.duration_ms ?? 0) / 1000,
      tokens: tokensFrom(parseJson<DevtoolsUsage>(step.usage)),
      // the AI SDK reports token usage, not dollars
      cost: 0,
    },
    ...(input?.tools?.length
      ? {
          available_tools: input.tools.map(
            (tool): RawToolDef => ({
              type: "function",
              name: tool.name ?? "unknown",
              ...(tool.description !== undefined ? { description: tool.description } : {}),
              ...(tool.parameters !== undefined ? { inputSchema: tool.parameters } : {}),
            }),
          ),
        }
      : {}),
    messages,
  };
}

/**
 * The step's own response messages. The telemetry integration writes them
 * verbatim (output.response.messages, including the step's tool results);
 * middleware-written steps only have collected parts to reconstruct from.
 */
function responseMessages(output: DevtoolsOutput | undefined): DevtoolsMessage[] {
  if (!output) return [];
  if (Array.isArray(output.response?.messages)) return output.response.messages;
  const parts: DevtoolsPart[] = [
    ...(output.reasoningParts ?? []).map((p) => ({ type: "reasoning", text: p.text })),
    ...(output.textParts ?? []).map((p) => ({ type: "text", text: p.text })),
    ...(output.toolCalls ?? []),
  ];
  if (parts.length === 0 && Array.isArray(output.content)) {
    parts.push(...output.content.filter((p) => p?.type !== "tool-result"));
  }
  return parts.length ? [{ role: "assistant", content: parts }] : [];
}

/** Splits tool messages into one result per part; extracts assistant tool calls. */
function convertMessage(message: DevtoolsMessage): RawMessage[] {
  if (message.role === "tool" && Array.isArray(message.content)) {
    return (message.content as DevtoolsPart[])
      .filter((part) => part?.type === "tool-result")
      .map(toolResultMessage);
  }
  if (message.role === "assistant" && Array.isArray(message.content)) {
    const parts = message.content as DevtoolsPart[];
    const calls = parts.filter((part) => part?.type === "tool-call");
    return [
      {
        role: "assistant",
        content: parts.filter((part) => part?.type !== "tool-call"),
        ...(calls.length ? { tool_calls: calls.map(toolCall) } : {}),
      },
    ];
  }
  return [{ role: message.role, content: message.content }];
}

function toolCall(part: DevtoolsPart, index: number): RawToolCall {
  return {
    type: "function",
    id: part.toolCallId ?? `call_${index}`,
    function: { name: part.toolName ?? "unknown", arguments: parseArgs(part.input) },
  };
}

/** Middleware-written steps store tool args as JSON strings; telemetry stores objects. */
function parseArgs(input: unknown): unknown {
  if (typeof input !== "string") return input;
  try {
    return JSON.parse(input);
  } catch {
    return input;
  }
}

function toolResultMessage(part: DevtoolsPart): RawMessage {
  const output = part.output as { type?: unknown; value?: unknown } | undefined;
  const wrapped =
    output !== null && typeof output === "object" && "value" in output && "type" in output;
  return {
    role: "tool",
    content: wrapped ? output.value : part.output,
    tool_call_id: part.toolCallId,
    ...(wrapped && typeof output.type === "string" && output.type.startsWith("error")
      ? { success: false }
      : {}),
  };
}

/**
 * Handles every usage shape @ai-sdk/devtools has written: current
 * ({inputTokens: n, inputTokenDetails}), provider-level V4 breakdown
 * objects, and legacy {inputTokens, cachedInputTokens}. Totals include
 * cache reads already.
 */
function tokensFrom(usage: DevtoolsUsage | undefined): RawEvent["metrics"]["tokens"] {
  const cacheRead =
    usage?.inputTokenDetails?.cacheReadTokens ??
    (typeof usage?.inputTokens === "object" ? usage.inputTokens?.cacheRead : undefined) ??
    usage?.cachedInputTokens;
  const reasoning =
    usage?.outputTokenDetails?.reasoningTokens ??
    (typeof usage?.outputTokens === "object" ? usage.outputTokens?.reasoning : undefined);
  return {
    input: numberOrTotal(usage?.inputTokens),
    output: numberOrTotal(usage?.outputTokens),
    ...(typeof cacheRead === "number" ? { cache_read: cacheRead } : {}),
    ...(typeof reasoning === "number" && reasoning > 0 ? { reasoning } : {}),
  };
}

function numberOrTotal(value: number | { total?: number } | undefined): number {
  if (typeof value === "number") return value;
  return typeof value?.total === "number" ? value.total : 0;
}

function parseJson<T>(text: string | null | undefined): T | undefined {
  if (typeof text !== "string") return undefined;
  try {
    return JSON.parse(text) as T;
  } catch {
    return undefined;
  }
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["src/**/*.test.ts"],
    environment: "node",
  },
});

import { describe, expect, it } from "vitest";
import { aggregateBy } from "./aggregate";
import { normalizeTrace } from "./normalize";
import type { RawEvent, RawMessage, RawTrace } from "./types";

function trace(events: RawEvent[]): RawTrace {
  return {
    trace_id: "t1",
    timestamp: "2026-08-25T10:00:00.000Z",
    name: "test",
    total_tokens: { input: 0, output: 0 },
    total_cost: 0,
    events,
  };
}

function event(messages: RawMessage[], overrides: Partial<RawEvent> = {}): RawEvent {
  return {
    type: "generation",
    name: "agent",
    model: "model",
    provider: "provider",
    metrics: { latency: 1, tokens: { input: 10, output: 1 }, cost: 1 },
    messages,
    ...overrides,
  };
}

const USER: RawMessage = { role: "user", content: "hello" };

function toolCall(id: string, name: string): RawMessage {
  return {
    role: "assistant",
    content: "",
    tool_calls: [{ type: "function", id, function: { name, arguments: {} } }],
  };
}

function sampleTrace() {
  return normalizeTrace(
    trace([
      event([{ role: "user", content: "one" }, toolCall("a1", "search")], {
        name: "agent-a",
        model: "model-z",
        metrics: { latency: 1, tokens: { input: 10, output: 1 }, cost: 2 },
        available_tools: [{ type: "function", name: "a" }],
      }),
      event([USER], {
        name: "agent-b",
        model: "model-a",
        metrics: { latency: 2, tokens: { input: 20, output: 2 }, cost: 5 },
        available_tools: [
          { type: "function", name: "a" },
          { type: "function", name: "b" },
        ],
      }),
      event(
        [
          { role: "user", content: "three" },
          {
            role: "assistant",
            content: "",
            tool_calls: [
              { type: "function", id: "a2", function: { name: "search", arguments: {} } },
              { type: "function", id: "a3", function: { name: "click", arguments: {} } },
            ],
          },
        ],
        {
          name: "agent-a",
          model: "model-a",
          metrics: { latency: 3, tokens: { input: 30, output: 3 }, cost: 3 },
          available_tools: [
            { type: "function", name: "a" },
            { type: "function", name: "b" },
            { type: "function", name: "c" },
          ],
        },
      ),
