/**
 * Resolves a dot/bracket pointer like "events[3].messages[2].content" against
 * a raw trace - the same pointer syntax `unbox-ai get` accepts and truncation
 * hints print.
 */
export function resolvePath(root: unknown, path: string): unknown {
  const segments = path.match(/[^.[\]]+/g) ?? [];
  let current: unknown = root;
  for (const segment of segments) {
    if (current === null || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

import { toolCallNames } from "./normalize";
import type { NormalizedTrace } from "./types";

export type AggregateKey = "model" | "agent" | "segment";

export interface AggregateRow {
  key: string;
  label?: string;
  generations: number;
  inputTokens: number;
  cachedTokens: number;
  outputTokens: number;
  latency: number;
  cost: number;
  toolCalls: number;
}

export function aggregateBy(trace: NormalizedTrace, key: AggregateKey): AggregateRow[] {
  const rows = new Map<string, AggregateRow>();
  for (const generation of trace.generations) {
    const rowKey =
      key === "model"
        ? generation.model
        : key === "agent"
          ? generation.name
          : String(generation.segment);
    const row = rows.get(rowKey) ?? {
      key: rowKey,
      ...(key === "segment" ? { label: generation.name } : {}),
      generations: 0,
      inputTokens: 0,
      cachedTokens: 0,
      outputTokens: 0,
      latency: 0,
      cost: 0,
      toolCalls: 0,
    };
    row.generations += 1;
    row.inputTokens += generation.metrics.inputTokens;
    row.cachedTokens += generation.breakdown.cacheableTokens;
    row.outputTokens += generation.metrics.outputTokens;
    row.latency += generation.metrics.latency;
    row.cost += generation.metrics.cost;
    row.toolCalls += toolCallNames(generation).length;
    rows.set(rowKey, row);
  }

  return [...rows.values()].sort((a, b) => {
    if (key === "segment") return Number(a.key) - Number(b.key);
    if (b.cost !== a.cost) return b.cost - a.cost;
    return a.key < b.key ? -1 : a.key > b.key ? 1 : 0;
  });
}

export interface DiffLine {
  kind: "same" | "added" | "removed";
  text: string;
}

/** DP-table cells above which diffing is skipped (~64MB of Int32 rows). */
const MAX_CELLS = 16_000_000;

/**
 * Classic LCS line diff: removed lines come from `a`, added from `b`.
 * Returns undefined for pathologically large inputs instead of stalling.
 */
export function diffLines(a: string[], b: string[]): DiffLine[] | undefined {
  if ((a.length + 1) * (b.length + 1) > MAX_CELLS) return undefined;
  const width = b.length + 1;
  const lcs = new Int32Array((a.length + 1) * width);
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      lcs[i * width + j] =
        a[i] === b[j]
          ? lcs[(i + 1) * width + j + 1]! + 1
          : Math.max(lcs[(i + 1) * width + j]!, lcs[i * width + j + 1]!);
    }
  }
  const lines: DiffLine[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      lines.push({ kind: "same", text: a[i]! });
      i++;
      j++;
    } else if (lcs[(i + 1) * width + j]! >= lcs[i * width + j + 1]!) {
      lines.push({ kind: "removed", text: a[i]! });
      i++;
    } else {
      lines.push({ kind: "added", text: b[j]! });
      j++;
    }
  }
  for (; i < a.length; i++) lines.push({ kind: "removed", text: a[i]! });
  for (; j < b.length; j++) lines.push({ kind: "added", text: b[j]! });
  return lines;
}

/**
 * Unwraps the tool runtime's `{"type":...,"value":...}` payload envelope:
 * string values render as plain text with real newlines, object values as
 * indented JSON. Non-JSON text passes through untouched.
 */
export function prettyPayload(text: string): string {
  try {
    const parsed: unknown = JSON.parse(text);
    const value =
      parsed !== null && typeof parsed === "object" && "value" in parsed
        ? (parsed as { value: unknown }).value
        : parsed;
    return renderValue(value);
  } catch {
    return text;
  }
}

const BLOCK_CHARS = 200;

/**
 * Renders a payload value for humans: strings as-is, and flat objects as
 * `key: value` lines with multi-line string fields (diffs, logs) unescaped
 * into labeled blocks instead of staying one giant JSON-escaped line.
 */
function renderValue(value: unknown): string {
  if (typeof value === "string") return value;
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    const scalars: string[] = [];
    const blocks: string[] = [];
    for (const [key, v] of Object.entries(value)) {
      if (typeof v === "string" && (v.includes("\n") || v.length > BLOCK_CHARS)) {
        blocks.push(`${key}:\n${v}`);
      } else if (typeof v === "string") {
        scalars.push(`${key}: ${v}`);
      } else {
        const compact = JSON.stringify(v);
        if (compact !== undefined && compact.length > BLOCK_CHARS) {
          blocks.push(`${key}:\n${JSON.stringify(v, null, 2)}`);
        } else {
          scalars.push(`${key}: ${compact}`);
        }
      }
    }
    if (blocks.length > 0) return [...scalars, "", ...blocks].join("\n").trim();
    return JSON.stringify(value, null, 2);
  }
  return JSON.stringify(value, null, 2);
}

/** Compact args stay on one line; big ones get indented. */
export function prettyArgs(args: unknown): string {
  if (typeof args === "string") return args;
  const compact = JSON.stringify(args);
  return compact.length > 120 ? JSON.stringify(args, null, 2) : compact;
}

/** Formats a count compactly: 310334 -> "310.3k". */
export function formatCompact(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(n);
}

/** Formats a token count compactly: 310334 -> "310.3k". */
export const formatTokens = formatCompact;

/** "-" for zero: traces without price data (AI SDK devtools) report 0. */
export function formatCost(cost: number): string {
  return cost > 0 ? `$${cost.toFixed(4)}` : "-";
}

export function formatSeconds(seconds: number): string {
  return `${seconds.toFixed(2)}s`;
}

/** Formats a millisecond duration: 845 -> "845ms", 7085 -> "7.09s". */
export function formatMs(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  return formatSeconds(ms / 1000);
}

/** Collapses repeated tool names: [a,a,a,b] -> "a x3, b". */
export function formatCallNames(names: string[]): string {
  const counts = new Map<string, number>();
  for (const name of names) counts.set(name, (counts.get(name) ?? 0) + 1);
  return [...counts.entries()].map(([name, n]) => (n > 1 ? `${name} x${n}` : name)).join(", ");
}

/** Share of a whole as a percent string: (41, 100) -> "41%". */
export function formatPercent(part: number, whole: number): string {
  if (whole === 0) return "0%";
  return `${Math.round((part / whole) * 100)}%`;
}

